# Problem: longest 1-run allowing k flips of 0s in a binary array.
# Sliding window with at most k zeros inside; expand right, shrink left when over.
def max_consecutive_ones_after_k_flips(nums, k):
    left = zeros = best = 0
    for right, v in enumerate(nums):
        if v == 0:
            zeros += 1
        while zeros > k:
            if nums[left] == 0:
                zeros -= 1
            left += 1
        best = max(best, right - left + 1)
    return best
```

