# Problem: group sorted ints into maximal consecutive runs.
# Walk once: start new run on a gap (curr != prev + 1).
def group_consecutive(nums):
    if not nums:
        return []
    groups = [[nums[0]]]
    for x in nums[1:]:
        if x == groups[-1][-1] + 1:
            groups[-1].append(x)
        else:
            groups.append([x])
    return groups
```

